// Profile pictures drawn by the creator. Used for the Arena's contestants
// and offered to players as ready-made profile pictures. Inlined so the
// single-file build carries them.

export const PORTRAITS = [
  { id: 'curls', name: 'Star Band', src: 'data:image/webp;base64,' },
  { id: 'beanie', name: 'Beanie', src: 'data:image/webp;base64,' },
  { id: 'snapback', name: 'Snapback', src: 'data:image/webp;base64,' },
  { id: 'varsity', name: 'Varsity', src: 'data:image/webp;base64,' },
  { id: 'scarf', name: 'Wrapped', src: 'data:image/webp;base64,' },
]
export const portraitById = (id) => PORTRAITS.find((p) => p.id === id) || null
